using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using LastRail.Auth;
using LastRail.Run;
using LastRail.Presentation.MissionShell;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public sealed class OfflineAdRuntimeTests {
  [Test] public void RouletteDiscHasNativeRenderer(){var g=new UnityEngine.GameObject("disc",typeof(UnityEngine.RectTransform));try{g.AddComponent<LobbyCommandDeck.RouletteDiscGraphic>();Assert.That(g.GetComponent<UnityEngine.CanvasRenderer>(),Is.Not.Null);}finally{UnityEngine.Object.DestroyImmediate(g);}}
  sealed class Wire:IRunApiHttpTransport {public List<RunApiHttpRequest> Calls=new();public Func<RunApiHttpRequest,Task<RunApiHttpResponse>> Reply;public readonly AdStartTestProtocol Protocol=new();public Task<RunApiHttpResponse> SendAsync(RunApiHttpRequest r){Calls.Add(r);return Protocol.Send(r,Reply);}}
  sealed class Journal:IAccountActionJournal,IAccountAdActionJournal {public PendingAccountAction Row;public bool FailReplace;public PendingAccountAction Read(string a)=>Row?.Account==a?Row:null;public bool Save(PendingAccountAction r){if(Row!=null)return false;Row=r;return true;}public bool Remove(PendingAccountAction r){if(Row!=r)return false;Row=null;return true;}public bool ReplaceAd(PendingAccountAction old,PendingAccountAction next){if(FailReplace||Row!=old)return false;Row=next;return true;}}
  sealed class Ad:IRewardAdPresentation {public bool Available=>true;public int Shows;public Task ShowAsync(string u,string c,string a){Shows++;return Task.CompletedTask;}}
  static GameApiAuthSessionSnapshot Session(string id="a")=>new(id,"ACTIVE",new GameApiAccessToken("lst1.fixture"),DateTime.UtcNow.AddMinutes(5),new GameApiRefreshToken("fixture"),DateTime.UtcNow.AddMinutes(10));
  static Task<RunApiHttpResponse> Reply(string sample,int status=200)=>Task.FromResult(RunApiHttpResponse.Success(status,OfflineAdContractTests.Sample(sample)));
  static string Key(RunApiHttpRequest r)=>r.Headers.Single(h=>h.Name=="Idempotency-Key").Value;
  static PendingAccountAction Saved(string phase="ad-presented",string sample="verified") {var p=OfflineAdIntent.Parse(OfflineAdContractTests.Sample(sample));return new("a",phase,p.Id,0,"original_key",p.Json);}
  static Task<RunApiHttpResponse> ReplyWithPolicy(string sample){var data=Newtonsoft.Json.Linq.JObject.Parse(OfflineAdContractTests.Sample(sample));data["probabilities"]=Newtonsoft.Json.Linq.JArray.Parse("[{\"multiplier\":2,\"weightBps\":10000},{\"multiplier\":3,\"weightBps\":0},{\"multiplier\":4,\"weightBps\":0}]");return Task.FromResult(RunApiHttpResponse.Success(200,data.ToString()));}
  [Test] public async Task LegacySpinRecoveryRetainsNewServerProbabilities(){
   var w=new Wire{Reply=q=>q.EndpointPath.EndsWith("/spin")?Reply("spin-claimed"):q.EndpointPath.Contains("ad-intents")?ReplyWithPolicy("verified"):Task.FromResult(RunApiHttpResponse.NetworkError("outside fixture"))};
   var j=new Journal{Row=Saved("ad-spin")};var s=Session();using var state=new AccountScreenRuntime(w,j,()=>s,()=>1);
   await state.RecheckAdAsync();Assert.That(state.AdIntent.Status,Is.EqualTo("CLAIMED"));
   Assert.That(state.AdIntent.ProbabilityText,Does.Contain("2배  100%"));Assert.That(OfflineAdIntent.Parse(j.Row.Payload).ProbabilityText,Does.Contain("2배  100%"));
  }
  [Test] public async Task MissingProviderDoesNotCreateIntent(){var w=new Wire();var j=new Journal();var s=Session();using var r=new AccountScreenRuntime(w,j,()=>s,()=>1);await r.BeginAdAsync();Assert.That(w.Calls.All(q=>q.Method=="GET"),Is.True);Assert.That(j.Row,Is.Null);}
  [Test] public async Task SdkCompletionOnlyRechecksServerAndPendingCannotSpin(){var w=new Wire{Reply=q=>Reply("pending")};w.Protocol.FreshAdvertising=true;var j=new Journal();var s=Session();var ad=new Ad();using var r=new AccountScreenRuntime(w,j,()=>s,()=>1);r.ConfigureRewardAds(ad);await r.BeginAdAsync();await r.RecheckAdAsync();await r.SpinAdAsync();Assert.That(ad.Shows,Is.EqualTo(1));Assert.That(r.CanSpinAd,Is.False);Assert.That(w.Calls.Count(q=>q.EndpointPath.EndsWith("/spin")),Is.Zero);Assert.That(w.Calls.All(q=>q.BodyJson==null),Is.True);}
  [Test] public async Task UnconfiguredPolicyReleasesNewIntentWithoutPresentingAd(){var w=new Wire{Reply=q=>Reply("policy-unconfigured",503)};var j=new Journal();var s=Session();var ad=new Ad();using var r=new AccountScreenRuntime(w,j,()=>s,()=>1);r.ConfigureRewardAds(ad);await r.BeginAdAsync();Assert.That(j.Row,Is.Null);Assert.That(ad.Shows,Is.Zero);}
  [Test] public async Task LostSpinResponseRestoresSameKeyWithoutProvider(){var keys=new List<string>();var w=new Wire();int spins=0;w.Reply=q=>{if(!q.EndpointPath.EndsWith("/spin"))return Reply("verified");keys.Add(Key(q));return ++spins==1?Task.FromResult(RunApiHttpResponse.NetworkError("local lost reply")):Reply("spin-claimed");};var j=new Journal{Row=Saved()};var s=Session();using(var r=new AccountScreenRuntime(w,j,()=>s,()=>1)){await r.SpinAdAsync();Assert.That(j.Row.Kind,Is.EqualTo("ad-spin"));Assert.That(r.AdIntent.Result,Is.Null);}using(var restored=new AccountScreenRuntime(w,j,()=>s,()=>1)){await restored.RecheckAdAsync();Assert.That((int)restored.AdIntent.Result["multiplier"],Is.EqualTo(2));Assert.That(restored.AdIntent.Result["rewardLines"].Count(),Is.EqualTo(4));Assert.That(keys.Distinct().Count(),Is.EqualTo(1));restored.AcknowledgeAdResult();Assert.That(j.Row,Is.Null);}}
  [Test] public async Task AtomicWriteFailurePreventsSpin(){var w=new Wire{Reply=q=>Reply("verified")};var j=new Journal{Row=Saved(),FailReplace=true};var s=Session();using var r=new AccountScreenRuntime(w,j,()=>s,()=>1);await r.SpinAdAsync();Assert.That(w.Calls.Count(q=>q.Method=="POST"),Is.Zero);Assert.That(j.Row.Kind,Is.EqualTo("ad-presented"));}
  [Test] public async Task DuplicateClickAndAccountReplacementCannotPublishOldReply(){var pending=new TaskCompletionSource<RunApiHttpResponse>();var w=new Wire{Reply=q=>pending.Task};var j=new Journal{Row=Saved()};var s=Session();long generation=1;using var r=new AccountScreenRuntime(w,j,()=>s,()=>generation);var first=r.SpinAdAsync();await r.SpinAdAsync();Assert.That(w.Calls.Count,Is.EqualTo(1));s=Session("b");generation++;r.SynchronizeSession();pending.SetResult(RunApiHttpResponse.Success(200,OfflineAdContractTests.Sample("verified")));await first;Assert.That(r.AdIntent,Is.Null);Assert.That(r.Pending,Is.Null);Assert.That(j.Row.Account,Is.EqualTo("a"));}
  [Test] public async Task ExistingClaimedIntentRestoresWithoutAdOrSpin(){var w=new Wire{Reply=q=>Reply("claimed-restored")};var j=new Journal{Row=Saved()};var s=Session();using var r=new AccountScreenRuntime(w,j,()=>s,()=>1);await r.RecheckAdAsync();Assert.That(r.AdIntent.Status,Is.EqualTo("CLAIMED"));Assert.That(w.Calls.All(q=>q.Method=="GET"),Is.True);Assert.That(r.CanSpinAd,Is.False);}
  [TestCase("EXPIRED")][TestCase("SUPPLY_CONSUMED")]
  public async Task TerminalSpinRestorationReleasesJournalOnAcknowledgment(string status){var data=Newtonsoft.Json.Linq.JObject.Parse(OfflineAdContractTests.Sample("pending"));data["status"]=status;var w=new Wire{Reply=q=>Task.FromResult(RunApiHttpResponse.Success(200,data.ToString()))};var j=new Journal{Row=Saved("ad-spin")};var s=Session();using var r=new AccountScreenRuntime(w,j,()=>s,()=>1);await r.RecheckAdAsync();Assert.That(r.AdIntent.Status,Is.EqualTo(status));Assert.That(w.Calls.All(q=>q.Method=="GET"),Is.True);r.AcknowledgeAdResult();Assert.That(j.Row,Is.Null);}
  [Test] public async Task PreviousAcknowledgedResultCannotDeleteNewUncertainCreate(){bool lost=false;var w=new Wire{Reply=q=>lost?Task.FromResult(RunApiHttpResponse.NetworkError("lost create")):Reply("claimed-restored")};var j=new Journal{Row=Saved()};var s=Session();using var r=new AccountScreenRuntime(w,j,()=>s,()=>1);r.ConfigureRewardAds(new Ad());await r.RecheckAdAsync();r.AcknowledgeAdResult();lost=true;await r.BeginAdAsync();var pending=j.Row;Assert.That(pending.Kind,Is.EqualTo("ad-create"));Assert.That(r.AdIntent,Is.Null);r.AcknowledgeAdResult();Assert.That(j.Row,Is.SameAs(pending));}
  [Test] public void ClaimedReceiptCannotRegressOrChange(){var claimed=OfflineAdIntent.Parse(OfflineAdContractTests.Sample("claimed-restored"));var verified=OfflineAdIntent.Parse(OfflineAdContractTests.Sample("verified"));Assert.Throws<FormatException>(()=>verified.RequireSame(claimed));var changed=Newtonsoft.Json.Linq.JObject.Parse(claimed.Json);changed["result"]["rewardLines"][0]["quantity"]=1;Assert.Throws<FormatException>(()=>OfflineAdIntent.Parse(changed.ToString()).RequireSame(claimed));}
  [TestCase("ad_daily_limit_reached")][TestCase("offline_reward_not_claimable")]
  public async Task DefinitiveNoIntentRejectionDoesNotBlockOtherActions(string code){var w=new Wire{Reply=q=>Task.FromResult(RunApiHttpResponse.Success(409,"{\"accepted\":false,\"errorCode\":\""+code+"\"}"))};var j=new Journal();var s=Session();var ad=new Ad();using var r=new AccountScreenRuntime(w,j,()=>s,()=>1);r.ConfigureRewardAds(ad);await r.BeginAdAsync();Assert.That(j.Row,Is.Null);Assert.That(ad.Shows,Is.Zero);}
  [Test] public async Task ConfirmedResultRetriesFailedBalanceRefresh(){var w=new Wire{Reply=q=>q.EndpointPath.Contains("ad-intents")?Reply("claimed-restored"):Task.FromResult(RunApiHttpResponse.NetworkError("local unavailable"))};var j=new Journal{Row=Saved()};var s=Session();using var r=new AccountScreenRuntime(w,j,()=>s,()=>1);await r.RecheckAdAsync();int queries=w.Calls.Count(q=>!q.EndpointPath.Contains("ad-intents"));Assert.That(queries,Is.GreaterThanOrEqualTo(3));await r.RecheckAdAsync();Assert.That(w.Calls.Count(q=>!q.EndpointPath.Contains("ad-intents")),Is.GreaterThan(queries));Assert.That(r.AccountStatus,Is.Not.EqualTo(AccountStateReadStatus.Loading));}
  [Test] public async Task ActualNativeOfflineButtonsShowVerifiedThenFixedResultAndRebindOnce(){
   foreach(var asset in new[]{"roulette-ring","roulette-pointer","roulette-room"}){var importer=(UnityEditor.TextureImporter)UnityEditor.AssetImporter.GetAtPath("Assets/_LASTRAIL/Resources/EntryPopup/"+asset+".png");importer.npotScale=UnityEditor.TextureImporterNPOTScale.None;importer.maxTextureSize=2048;importer.textureCompression=UnityEditor.TextureImporterCompression.Uncompressed;importer.alphaIsTransparency=asset!="roulette-room";importer.mipmapEnabled=false;importer.SaveAndReimport();}
   string previewPath=System.IO.Path.Combine(UnityEngine.Application.dataPath,"../QA/Unity1Artifacts/Reports/Server2-AdSamples-20260914/BasicPreview01/preview.json");Assert.That(LastRail.Qa.MapGrayboxFixtureGeometry.Hash(previewPath),Is.EqualTo("655ebfd2f0b5d35023d2a6dc2139ab2f69eb7f3251ba93b7ea17aba71057bc10"));string preview=System.IO.File.ReadAllText(previewPath);
   bool granted=false;var w=new Wire{Reply=q=>{if(q.EndpointPath.EndsWith("/spin")){granted=true;return Reply("spin-claimed");}if(q.EndpointPath=="/v1/offline-rewards/preview")return Task.FromResult(RunApiHttpResponse.Success(200,preview));return q.EndpointPath.Contains("ad-intents")?ReplyWithPolicy(granted?"claimed-restored":"verified"):Task.FromResult(RunApiHttpResponse.NetworkError("outside local fixture"));}};var j=new Journal{Row=Saved()};var s=Session();using var state=new AccountScreenRuntime(w,j,()=>s,()=>1);
   var root=new UnityEngine.GameObject("ActualOfflineAdUi",typeof(UnityEngine.RectTransform),typeof(UnityEngine.Canvas),typeof(UnityEngine.UI.GraphicRaycaster));((UnityEngine.RectTransform)root.transform).sizeDelta=new UnityEngine.Vector2(720,1280);
   var safe=new UnityEngine.GameObject("SafeArea",typeof(UnityEngine.RectTransform));safe.transform.SetParent(root.transform,false);var sr=(UnityEngine.RectTransform)safe.transform;sr.anchorMin=UnityEngine.Vector2.zero;sr.anchorMax=UnityEngine.Vector2.one;sr.sizeDelta=UnityEngine.Vector2.zero;
   try{
    var deck=LobbyCommandDeck.Attach(root,UnityEditor.AssetDatabase.LoadAssetAtPath<TMPro.TMP_FontAsset>("Assets/_LASTRAIL/UI/StartupResources/BootstrapFont.asset"),"LOCAL QA",1,new MissionShellMissionRowState[0],null,null);deck.BindAccount(state);deck.BindAccount(state);
    root.GetComponentsInChildren<UnityEngine.UI.Button>().Single(b=>b.name=="Shortcut3").onClick.Invoke();while(state.Busy)await Task.Yield();
    root.GetComponentsInChildren<UnityEngine.UI.Button>().Single(b=>b.name=="OpenOfflineRoulette").onClick.Invoke();while(state.Busy)await Task.Yield();var action=root.GetComponentsInChildren<UnityEngine.UI.Button>().Single(b=>b.name=="AdMainAction");Assert.That(action.interactable,Is.True);Assert.That(action.GetComponentInChildren<TMPro.TMP_Text>().text,Is.EqualTo("룰렛 돌리기"));Assert.That(state.Offline,Is.Not.Null);var previewValues=new[]{400,200,120,80};for(int i=0;i<4;i++)Assert.That(root.GetComponentsInChildren<TMPro.TMP_Text>().Single(t=>t.name=="RewardQuantity"&&t.transform.parent.name=="RewardCard"+i).text,Does.EndWith(previewValues[i].ToString()));Capture(root,"verified");
    root.GetComponentsInChildren<UnityEngine.UI.Button>().Single(b=>b.name=="RouletteOdds").onClick.Invoke();
    Assert.That(root.GetComponentsInChildren<TMPro.TMP_Text>().Single(t=>t.name=="OddsText").text,Does.Contain("2배  100%"));
    Capture(root,"probabilities");root.GetComponentsInChildren<UnityEngine.UI.Button>().Single(b=>b.name=="CloseOdds").onClick.Invoke();
    action.onClick.Invoke();while(state.Busy)await Task.Yield();Assert.That(w.Calls.Count(q=>q.EndpointPath.EndsWith("/spin")),Is.EqualTo(1));Assert.That(root.GetComponentsInChildren<TMPro.TMP_Text>().Single(t=>t.name=="CommittedMultiplier").text,Is.EqualTo("×2"));Capture(root,"claimed");
    foreach(var role in new[]{"MechanicalRing","Pointer","RouletteRoom"}){var graphic=root.GetComponentsInChildren<UnityEngine.UI.RawImage>().Single(g=>g.name==role);Assert.That(graphic.raycastTarget,Is.False);var texture=graphic.texture;graphic.texture=UnityEngine.Texture2D.whiteTexture;Capture(root,"swap-"+role);graphic.texture=texture;}
    foreach(var graphic in root.GetComponentsInChildren<LobbyCommandDeck.RouletteDiscGraphic>()){Assert.That(graphic.canvasRenderer.GetMesh().vertexCount,Is.GreaterThan(0));Assert.That(graphic.raycastTarget,Is.False);}
    Capture(root,"restored");deck.CloseDialog();root.GetComponentsInChildren<UnityEngine.UI.Button>().Single(b=>b.name=="Shortcut3").onClick.Invoke();while(state.Busy)await Task.Yield();root.GetComponentsInChildren<UnityEngine.UI.Button>().Single(b=>b.name=="OpenOfflineRoulette").onClick.Invoke();while(state.Busy)await Task.Yield();Assert.That(root.GetComponentsInChildren<UnityEngine.UI.Button>().Count(b=>b.name=="AdMainAction"),Is.EqualTo(1));Capture(root,"rebound");
   }finally{UnityEngine.Object.DestroyImmediate(root);}
  }
  static void Capture(UnityEngine.GameObject root,string name){typeof(AccountScreenIntegrationTests).GetMethod("Capture",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,new object[]{root,"gallery27-"+name+"-05.png"});foreach(var text in root.GetComponentsInChildren<TMPro.TMP_Text>()){text.ForceMeshUpdate();Assert.That(text.text,Does.Not.Contain("광고 시청 완료"));}}
 }
